 static int count;
 static void Check(bool condition,string name){if(!condition)throw new Exception("FAIL "+name);count++;Console.WriteLine("PASS "+name);}
 static void Reject(Action action,string name){try{action();}catch(SafeError){Check(true,name);return;}throw new Exception("Expected rejection: "+name);}
 static int Main(){string folder=Path.Combine(Path.GetTempPath(),"ShixunAiTests-"+Guid.NewGuid().ToString("N"));try{
 Check(!new AiSettings().enabled&&!new AiSettings().allowPrivate,"AI and private sending disabled by default");Reject(()=>AiService.Validate(new AiSettings{enabled=true}),"enabled AI requires endpoint and model");Reject(()=>AiService.Validate(new AiSettings{endpoint="http://example.com/chat/completions"}),"external AI requires HTTPS");Reject(()=>AiService.Validate(new AiSettings{endpoint="https://example.com/chat?key=fixture"}),"AI endpoint query secrets rejected");
 var categories=new List<Category>{new Category{id="tech",name="技术"}};string normal=Response("{\"title\":\"离线阅读工具更新\",\"categoryId\":\"tech\",\"rating\":4,\"reason\":\"提供离线阅读与搜索，信息较完整。\"}");var result=AiService.Parse(normal,categories);Check(result.title=="离线阅读工具更新"&&result.rating==4&&result.categoryId=="tech","structured AI title/category/rating parsed");Check(!Data.Json().Serialize(result).Contains("private-thought"),"reasoning content never stored");Reject(()=>AiService.Parse(Response("{\"title\":\"x\",\"categoryId\":\"tech\",\"rating\":9}"),categories),"out-of-range rating rejected");Reject(()=>AiService.Parse("{\"choices\":[{\"finish_reason\":\"length\",\"message\":{\"content\":\"{}\"}}]}",categories),"truncated model result rejected");var unknown=AiService.Parse(Response("{\"title\":\"未知分类文章\",\"categoryId\":\"invented-category\",\"rating\":3}"),categories);Check(unknown.categoryId=="","AI cannot invent category IDs");var fence=AiService.Parse(Response("```json\n{\"title\":\"短标题\",\"categoryId\":\"tech\",\"rating\":3}\n```"),categories);Check(fence.title=="短标题","fenced JSON compatibility");
 var article=new Article{id="a",source="s",title=new string('长',200)+"[图片]",summary="离线阅读工具 https://private.example.com/path?token=fixture-source-token"};var settings=new AiSettings{enabled=true,endpoint="https://example.com/v1/chat/completions",model="normal-model"};string body=Data.Json().Serialize(AiService.Body(article,settings,categories));Check(!body.Contains("fixture-source-token")&&!body.Contains("private.example.com"),"article URLs removed from outgoing AI text");Check(Feeds.ShortTitle(article.title).Length<=45&&!Feeds.ShortTitle(article.title).Contains("[图片]"),"long fallback title compact without image placeholders");settings.mode="reasoning";settings.tokenField="max_completion_tokens";settings.reasoningEffort="high";var reasoning=AiService.Body(article,settings,categories);Check(reasoning.ContainsKey("max_completion_tokens")&&!reasoning.ContainsKey("max_tokens")&&Convert.ToString(reasoning["reasoning_effort"])=="high","reasoning mode uses selected compatible token field");Check(!reasoning.ContainsKey("temperature"),"reasoning requests omit unsupported sampling parameters");
 using(var server=new Server(normal)){var store=new Store(folder);store.State.categories=categories;store.State.sources.Add(new Source{id="s",name="私有来源",url="https://private.example.com/feed",privateSource=true});store.State.articles.Add(article);store.State.ai=new AiSettings{enabled=true,model="fixture-model",endpoint=server.Url,dailyLimit=1};store.State.credentials["s"]=new RequestProfile{mode="bearer",token="fixture-source-token"};store.State.credentials[AiService.CredentialKey]=new RequestProfile{mode="bearer",token="fixture-ai-token"};var service=new AiService(store);Reject(()=>service.Analyze("a").GetAwaiter().GetResult(),"private content requires explicit opt-in");Check(server.Requests==0,"blocked private content makes no network request");Check(store.State.aiHistory.Last().status=="blocked"&&store.State.articles[0].aiError.Length>0,"private preflight rejection is visible in article and history");store.State.ai.allowPrivate=true;var analyzed=service.Analyze("a").GetAwaiter().GetResult();Check(analyzed.rating==4&&store.State.articles[0].category=="tech","real local AI request updates category and result");Check(server.Last.Contains("fixture-ai-token")&&!server.Last.Contains("fixture-source-token"),"AI credential isolated from feed credential");Check(store.State.articles[0].title==article.title&&store.State.articles[0].summary==article.summary,"original content remains unchanged");service.Analyze("a").GetAwaiter().GetResult();Check(server.Requests==1&&store.State.aiRequestsToday==1,"content fingerprint cache avoids repeat billing");Check(store.State.aiHistory.First().status=="cached","cache hits recorded without paid request");Reject(()=>service.Analyze("a",true).GetAwaiter().GetResult(),"daily request limit enforced");Check(server.Requests==1,"daily limit blocks actual network request");store.State.aiDay="2000-01-01";store.State.articles[0].locked=true;store.State.articles[0].category="manual";service.Analyze("a",true).GetAwaiter().GetResult();Check(store.State.articles[0].category=="manual","AI preserves manually locked category");Check(store.State.aiRequestsToday==1&&server.Requests==2,"daily request count resets on local date");server.Content=Response("{\"title\":\"bad\",\"rating\":0}");store.State.ai.dailyLimit=5;Reject(()=>service.Analyze("a",true).GetAwaiter().GetResult(),"invalid provider output is rejected in real request");Check(store.State.articles[0].ai.rating==4&&store.State.articles[0].aiError.Length>0,"failure retains prior AI result and records generic error");}
 using(var server=new Server(normal)){var unlimited=new Store(Path.Combine(folder,"unlimited"));unlimited.State.ai=new AiSettings{enabled=true,endpoint=server.Url,model="fixture",dailyLimit=0};unlimited.State.sources.Add(new Source{id="public",url="https://example.com/feed"});unlimited.State.articles.Add(new Article{id="free",source="public",title="测试工具"});unlimited.State.aiDay=DateTime.Now.ToString("yyyy-MM-dd");unlimited.State.aiRequestsToday=10001;new AiService(unlimited).Analyze("free").GetAwaiter().GetResult();Check(server.Requests==1&&unlimited.State.aiRequestsToday==10002,"zero quota allows actual AI call beyond former limits");Reject(()=>AiService.Validate(new AiSettings{dailyLimit=-1}),"negative daily quota rejected");}
 DigestTests(folder);EnrichmentTests(folder);MetricTests();RssTests();
 var usage=new AiRun();AiService.Usage("{\"usage\":{\"prompt_tokens\":123,\"completion_tokens\":45,\"total_tokens\":168,\"prompt_tokens_details\":{\"cached_tokens\":20},\"completion_tokens_details\":{\"reasoning_tokens\":10}}}",usage);Check(usage.usageKnown&&usage.totalTokens==168&&usage.inputTokens==123&&usage.cachedTokens==20&&usage.reasoningTokens==10,"usage records input/output/cache/reasoning without double count");var missing=new AiRun();AiService.Usage("{}",missing);Check(!missing.usageKnown,"missing usage remains unknown");var alias=new AiRun();AiService.Usage("{\"usage\":{\"prompt_tokens\":10,\"input_tokens\":10,\"completion_tokens\":5,\"output_tokens\":5}}",alias);Check(alias.totalTokens==15,"usage aliases do not duplicate tokens");Check(new ClientState().categories.Count==0,"fresh install has no categories");Console.WriteLine("RESULT: "+count+" AI checks passed");return 0;
 }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}finally{if(Directory.Exists(folder))Directory.Delete(folder,true);}}
 static void DigestTests(string folder){using(var server=new Server(ResponseWithUsage("今日摘要：一条公开内容。"))){var store=new Store(Path.Combine(folder,"digest"));store.State.ai=new AiSettings{enabled=true,endpoint=server.Url,model="fixture",dailyLimit=0};store.State.sources.Add(new Source{id="p",url="https://example.com/feed"});store.State.sources.Add(new Source{id="secret",url="https://example.com/private",privateSource=true});store.State.sources.Add(new Source{id="query",url="https://example.com/feed?key=fixture-feed-key"});store.State.credentials["@ai"]=new RequestProfile{mode="bearer",token="fixture-ai-key"};store.State.credentials["secret"]=new RequestProfile{mode="bearer",token="fixture-feed-secret"};store.State.articles.Add(new Article{id="public",source="p",title="公开工具",summary="正文 https://example.com/link?key=fixture-link-key",firstSeen=Data.Now(),time=Data.Now()-86400000d});store.State.articles.Add(new Article{id="private",source="secret",title="private-body-marker",firstSeen=Data.Now(),time=Data.Now()});store.State.articles.Add(new Article{id="query",source="query",title="query-body-marker",firstSeen=Data.Now(),time=Data.Now()});int included,excluded;string body=Data.Json().Serialize(AiService.DigestBody(store.State,store.State.ai,DateTime.Now,out included,out excluded));Check(included==1&&excluded==2&&body.Contains("公开工具")&&!body.Contains("private-body-marker")&&!body.Contains("query-body-marker")&&!body.Contains("fixture-link-key"),"digest honors private authorization and strips article URLs");Check(AiService.ReceivedToday(store.State.articles[0],DateTime.Now),"digest reception uses firstSeen instead of published date");var service=new AiService(store);var digest=service.SummarizeToday().GetAwaiter().GetResult();Check(digest.included==1&&digest.excluded==2&&digest.text.Contains("公开内容")&&new Store(store.Folder).State.digest.text==digest.text,"real local digest request is persisted with coverage");Check(server.Last.Contains("fixture-ai-key")&&!server.Last.Contains("fixture-feed-secret")&&!server.Last.Contains("private-body-marker"),"digest uses isolated AI credentials and never sends feed credentials");Check(store.State.aiHistory.First().kind=="digest"&&store.State.aiHistory.First().status=="success"&&store.State.aiRequestsToday==1,"digest shares AI request counter and audit history");var daily=Data.Json().Deserialize<Dictionary<string,object>>(Data.Json().Serialize(AiService.DailyUsage(store.State,DateTime.Now)));Check(store.State.aiTotalTokens==60&&Convert.ToInt64(daily["total"])==60&&Convert.ToInt32(daily["known"])==1,"digest tokens counted once in daily and cumulative usage");var hours=((System.Collections.IEnumerable)daily["hourly"]).Cast<object>().Cast<Dictionary<string,object>>().ToList();Check(hours.Count==24&&hours.Sum(h=>Convert.ToInt64(h["input"]))==40&&hours.Sum(h=>Convert.ToInt64(h["output"]))==20,"hourly token buckets reconcile with daily usage");server.Content=Response("");Reject(()=>service.SummarizeToday().GetAwaiter().GetResult(),"empty summary rejected");Check(store.State.digest.text==digest.text&&store.State.aiHistory.First().status=="failed","failed regeneration preserves previous digest");store.State.ai.dailyLimit=1;int before=server.Requests;Reject(()=>service.SummarizeToday().GetAwaiter().GetResult(),"digest respects explicit quota");Check(server.Requests==before,"digest quota blocks provider call");store.State.ai.dailyLimit=0;store.State.articles.RemoveAll(a=>a.source=="p");Reject(()=>service.SummarizeToday().GetAwaiter().GetResult(),"all-private unapproved digest is blocked before network");Check(server.Requests==before,"unapproved private digest makes no request");store.State.digest.day=DateTime.Now.AddDays(-1).ToString("yyyy-MM-dd");store.Clean();Check(store.State.digest==null,"expired digest cleared with article cleanup");}}
 static void EnrichmentTests(string folder){
  Check(AiService.ExplicitPrice("TB【凑单139.13】运动鞋")=="凑单¥139.13"&&AiService.ExplicitPrice("JD【凑单价88】测试")=="凑单¥88"&&AiService.ExplicitPrice("章节[2]")=="","explicit conditional shopping prices recognized without treating chapter numbers as prices");var p=new AiResult{price="价格未说明"};AiService.ValidatePrice(p,new Article{title="TB【凑单139.13】运动鞋"});Check(p.price=="凑单¥139.13","explicit price fills missing model result");var vision=new AiResult{price="到手¥88",priceEvidence="到手88元"};AiService.ValidatePrice(vision,new Article{title="图片商品"},true);Check(vision.priceFromImage&&AiService.DisplayTitle(vision,true).Contains("图示"),"image evidence price marked as image recognition");var unapproved=new AiResult{price="到手¥88",priceEvidence="到手88元"};AiService.ValidatePrice(unapproved,new Article{title="图片商品"},false);Check(unapproved.price=="价格未说明"&&!unapproved.priceFromImage,"image prices require actual image transfer");
  using(var server=new Server(Response("{\"title\":\"运动鞋\",\"price\":\"价格未说明\",\"categoryName\":\"鞋靴\",\"rating\":4,\"reason\":\"适合跑步\"}"))){var store=new Store(Path.Combine(folder,"enriched"));store.State.ai=new AiSettings{enabled=true,model="fixture",endpoint=server.Url,allowNewCategories=true};store.State.sources.Add(new Source{id="s",url="https://example.com/feed"});store.State.sources.Add(new Source{id="private",url="https://example.com/private",privateSource=true});var a=new Article{id="a",source="s",title="TB【凑单139.13】运动鞋",summary="测试商品"};store.State.articles.Add(a);var service=new AiService(store);service.Analyze("a").GetAwaiter().GetResult();Check(store.State.categories.Count==1&&a.category==store.State.categories[0].id&&a.ai.price=="凑单¥139.13","real analysis creates category and fills explicit price");var b=Data.Clone(a);b.id="b";b.ai=null;store.State.articles.Add(b);service.Analyze("b").GetAwaiter().GetResult();Check(server.Requests==1&&b.ai!=null&&store.State.aiHistory.First().status=="cached","duplicate content across article IDs reuses result without paid call");store.State.categories.Add(new Category{name="新分类"});service.Analyze("a").GetAwaiter().GetResult();Check(server.Requests==1,"new categories do not invalidate existing content cache");var locked=new Article{locked=true,category="manual"};AiService.ApplyCategory(store.State,locked,new AiResult{categoryName="其他"},store.State.ai);Check(locked.category=="manual"&&store.State.categories.Count==2,"automatic categories respect manual locks");var same=new AiResult{categoryName="鞋靴"};AiService.ApplyCategory(store.State,new Article(),same,store.State.ai);Check(store.State.categories.Count==2&&same.categoryId==a.category,"automatic categories deduplicate by name");
   store.State.articles.Add(new Article{id="history",source="s",title="历史偏好运动鞋",star=true});store.State.articles.Add(new Article{id="secret",source="private",title="private-history-marker",star=true});store.State.ai.useHistory=true;store.State.ai.systemPrompt="偏好耐用商品";var body=AiService.Body(a,store.State.ai,store.State.categories);AiService.AddHistory(body,store.State,store.State.ai,a);string sent=Data.Json().Serialize(body);Check(sent.Contains("历史偏好运动鞋")&&!sent.Contains("private-history-marker")&&sent.Contains("偏好耐用商品")&&sent.Contains("JSON"),"history reference respects private authorization and custom system keeps output contract");
   store.State.ai.useImages=true;int images=0;service.ImageLoader=(id,index)=>{images++;return Task.FromResult(new byte[]{255,216,255,0,1});};server.Content=Response("{\"title\":\"图片商品\",\"price\":\"到手¥88\",\"priceEvidence\":\"到手88元\",\"rating\":4}");var photo=new Article{id="photo",source="s",title="图片商品",images=new List<string>{"https://example.com/price.jpg"}};store.State.articles.Add(photo);service.Analyze("photo").GetAwaiter().GetResult();Check(images==1&&server.Last.Contains("data:image/jpeg;base64,")&&!server.Last.Contains("https://example.com/price.jpg")&&photo.ai.priceFromImage,"opted-in vision request uses inline image bytes without original image URL");store.State.ai.useImages=false;photo.title="图片商品二";service.Analyze("photo",true).GetAwaiter().GetResult();Check(images==1&&!server.Last.Contains("image_url")&&!photo.ai.priceFromImage,"vision disabled never uploads images");
  }
 }
 static void MetricTests(){var state=new ClientState();state.ai=new AiSettings{model="m",estimateCost=true,inputCost=2,outputCost=8};state.aiHistory.Add(new AiRun{model="m",kind="auto",status="success",usageKnown=true,inputTokens=100,outputTokens=20,totalTokens=120,cachedTokens=80,cacheUsageKnown=true});state.aiHistory.Add(new AiRun{model="m",kind="auto",status="cached"});state.aiHistory.Add(new AiRun{model="m",kind="auto",status="blocked"});var metrics=Data.Json().Deserialize<Dictionary<string,object>>(Data.Json().Serialize(AiService.DailyUsage(state,DateTime.Now)));Check(Convert.ToInt32(metrics["requests"])==1&&Math.Abs(Convert.ToDouble(metrics["providerCacheRate"])-80)<0.001&&Math.Abs(Convert.ToDouble(metrics["localCacheRate"])-50)<0.001,"provider token cache and local result reuse have separate accurate rates");Check(Math.Abs(Convert.ToDouble(metrics["estimatedCost"])-0.00036)<0.00000001,"configured unit rates produce explicitly estimated cost");state.aiHistory[0].cacheUsageKnown=false;state.aiHistory[0].cachedTokens=0;metrics=Data.Json().Deserialize<Dictionary<string,object>>(Data.Json().Serialize(AiService.DailyUsage(state,DateTime.Now)));Check(!Convert.ToBoolean(metrics["cacheKnown"]),"missing provider cache metrics remain unknown");}
 static void RssTests(){
 var s=new AiSettings{model="m",endpoint="https://example.com/v1/chat/completions",useHistory=true};var state=new ClientState{ai=s};state.sources.Add(new Source{id="s",url="https://example.com/feed"});var current=new Article{id="a",source="s",title="新闻：新系统上线",html="<p>上线后新增离线阅读，计划分阶段开放。</p>"};
 var ordinary=new Article{id="ordinary",source="s",title="ordinary-marker",ai=new AiResult{rating=5}};var favorite=new Article{id="favorite",source="s",title="favorite-marker",summary="收藏的阅读兴趣",star=true};state.articles.AddRange(new[]{current,ordinary,favorite});
 var categories=new List<Category>{new Category{id="z",name="新闻"},new Category{id="a",name="技术"}};var one=AiService.Body(current,s,categories);AiService.AddHistory(one,state,s,current);var text=Data.Json().Serialize(one);Check(text.Contains("favorite-marker")&&!text.Contains("ordinary-marker"),"only favorites inform personal preference, never model-rated history");
 var key=AiService.FavoritesKey(state,s);ordinary.ai.rating=1;Check(key==AiService.FavoritesKey(state,s),"ordinary rating changes never invalidate favorite preference cache");favorite.star=false;Check(key!=AiService.FavoritesKey(state,s),"unfavorite invalidates preference-dependent result key");favorite.star=true;
 var other=new Article{id="b",title="教程：如何备份",summary="另一篇完全不同的文章"};var two=AiService.Body(other,s,categories.AsEnumerable().Reverse().ToList());AiService.AddHistory(two,state,s,other);var a=(object[])one["messages"];var b=(object[])two["messages"];Check(Data.Json().Serialize(a.Take(a.Length-1).ToArray())==Data.Json().Serialize(b.Take(b.Length-1).ToArray()),"stable shared prefix precedes changing article and category input order is deterministic");Check(text.Contains("先识别文章类型")&&text.Contains("非购物文章price必须为空"),"RSS title contract adapts to news tutorials research and shopping");
 current.firstSeen=Data.Now();int included,excluded;var digest=Data.Json().Serialize(AiService.DigestBody(state,s,DateTime.Now,out included,out excluded));Check(digest.Contains("新增离线阅读")&&digest.Contains("今日文章总览")&&!digest.Contains("knownTokens"),"daily digest summarizes article bodies rather than AI operational statistics");
 string json="{\"p\":{\"name\":\"Provider\",\"models\":{\"m\":{\"cost\":{\"input\":2,\"output\":8,\"cache_read\":0.2}}}}}";
 var prices=ModelPricing.Parse(json,"m");Check(prices.Count==1&&prices[0].cacheReadKnown&&prices[0].cacheRead==0.2&&ModelPricing.Parse(json,"unknown").Count==0,"models.dev exact provider/model lookup with cache-read rate");
 ModelPricing.Apply(s,prices[0]);var run=new AiRun{usageKnown=true,inputTokens=100,outputTokens=20,cachedTokens=80};AiService.RecordCost(run,s);Check(run.costKnown&&run.costCurrency=="USD"&&Math.Abs(run.estimatedCost-0.000216)<0.000000001,"cost snapshots charge cached inputs at directory cache-read price");
 s.model="different";var mismatch=new AiRun{usageKnown=true,inputTokens=100};AiService.RecordCost(mismatch,s);Check(!mismatch.costKnown,"model changes cannot silently inherit unrelated directory prices");
 Reject(()=>AiService.Validate(new AiSettings{cacheReadCost=Double.NaN}),"invalid cache rate rejected");
 var nonShopping=new AiResult{articleType="news",title="新闻",price="到手¥88"};AiService.ValidatePrice(nonShopping,new Article{title="某企业营收88亿元"});Check(nonShopping.price=="","non-shopping article never displays a product price");
 var usage=new AiRun();AiService.Usage("{\"usage\":{\"input_tokens\":100,\"output_tokens\":10,\"input_tokens_details\":{\"cached_tokens\":80}}}",usage);Check(usage.cacheUsageKnown&&usage.cachedTokens==80,"compatible input token cache metrics captured");
 }
 static string ResponseWithUsage(string content){var value=Data.Json().Deserialize<Dictionary<string,object>>(Response(content));value["usage"]=new{prompt_tokens=40,completion_tokens=20,total_tokens=60};return Data.Json().Serialize(value);}
 static string Response(string content){return Data.Json().Serialize(new{choices=new[]{new{finish_reason="stop",message=new{content=content,reasoning_content="private-thought-not-for-storage"}}}});}
 sealed class Server:IDisposable {
 readonly TcpListener listener;readonly Task task;volatile bool stopped;public int Requests;public string Content,Last="",Url;
 public Server(string content){Content=content;listener=new TcpListener(IPAddress.Loopback,0);listener.Start();Url="http://127.0.0.1:"+((IPEndPoint)listener.LocalEndpoint).Port+"/v1/chat/completions";task=Task.Run(()=>{while(!stopped)try{using(var client=listener.AcceptTcpClient())using(var stream=client.GetStream()){client.ReceiveTimeout=5000;var buffer=new List<byte>();int value;while((value=stream.ReadByte())>=0){buffer.Add((byte)value);int n=buffer.Count;if(n>=4&&buffer[n-4]==13&&buffer[n-3]==10&&buffer[n-2]==13&&buffer[n-1]==10)break;}string headers=Encoding.UTF8.GetString(buffer.ToArray());int length=0;foreach(string line in headers.Split('\n'))if(line.StartsWith("Content-Length:",StringComparison.OrdinalIgnoreCase))int.TryParse(line.Substring(15).Trim(),out length);byte[] body=new byte[length];int read=0;while(read<length){int n=stream.Read(body,read,length-read);if(n<=0)break;read+=n;}Last=headers+Encoding.UTF8.GetString(body);Requests++;byte[] response=Encoding.UTF8.GetBytes(Content),head=Encoding.ASCII.GetBytes("HTTP/1.1 200 OK\r\nContent-Type: application/json; charset=utf-8\r\nContent-Length: "+response.Length+"\r\nConnection: close\r\n\r\n");stream.Write(head,0,head.Length);stream.Write(response,0,response.Length);}}catch{if(stopped)break;}});}
 public void Dispose(){stopped=true;listener.Stop();task.Wait(3000);}
 }
